import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const root = new Group();
  root.name = config.name || config.id || 'collection-title';
  root.userData.handlers = {};

  const ownedMaterials = [];
  const ownedGeometries = [];
  const primitiveCleanups = [];
  const timelines = [];

  const visualSpec = config.intent?.visualSpec || {};
  const colors = visualSpec.colors || {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const colorNode = (value) => {
    const c = new Color(value);
    return vec3(c.r, c.g, c.b);
  };

  const gradientStops = Array.isArray(visualSpec.gradientStops) && visualSpec.gradientStops.length >= 2
    ? visualSpec.gradientStops
    : [surface, ink, '#252631'];

  const backdropMaterial = new MeshBasicNodeMaterial();
  const gradientY = uv().y;
  const stopA = colorNode(gradientStops[0]);
  const stopB = colorNode(gradientStops[1]);
  const stopC = colorNode(gradientStops[2] || gradientStops[1]);

  const lowerBlend = smoothstep(0.0, 0.58, gradientY);
  const upperBlend = smoothstep(0.42, 1.0, gradientY);
  const gradientColor = mix(mix(stopA, stopB, lowerBlend), stopC, upperBlend);

  backdropMaterial.colorNode = vec4(gradientColor, 1.0);
  backdropMaterial.toneMapped = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  backdrop.userData.__owned = true;
  root.add(backdrop);

  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const frameMaterial = new MeshBasicNodeMaterial({ color: surface });
  frameMaterial.toneMapped = false;
  const frameGeometry = new PlaneGeometry(5.55, 3.15);
  const frame = new Mesh(frameGeometry, frameMaterial);
  frame.name = 'collection-image-frame';
  frame.position.set(0, -0.2, -1.35);
  frame.userData.__owned = true;
  root.add(frame);

  ownedGeometries.push(frameGeometry);
  ownedMaterials.push(frameMaterial);

  const imageMaterial = new MeshBasicNodeMaterial({ color: paper });
  imageMaterial.toneMapped = false;
  imageMaterial.transparent = true;
  imageMaterial.opacity = 0.96;

  const imageGeometry = new PlaneGeometry(5.2, 2.8);
  const imageLayer = new Mesh(imageGeometry, imageMaterial);
  imageLayer.name = 'collection-image';
  imageLayer.position.set(0, -0.2, -1.1);
  imageLayer.userData.__owned = true;
  root.add(imageLayer);

  ownedGeometries.push(imageGeometry);
  ownedMaterials.push(imageMaterial);

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!root.userData.__cleaned) {
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
      }
    }).catch(() => {});
  }

  const accentMaterial = new MeshBasicNodeMaterial({ color: accent });
  accentMaterial.toneMapped = false;
  const accentGeometry = new PlaneGeometry(0.08, 1.2);
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.name = 'signal-red-accent';
  accentBar.position.set(-2.82, 0.55, -0.35);
  accentBar.userData.__owned = true;
  root.add(accentBar);

  ownedGeometries.push(accentGeometry);
  ownedMaterials.push(accentMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'collection-title-text';
  textGroup.position.set(-2.35, 0.55, 0.15);
  root.add(textGroup);

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize || 96,
      color: item.typography?.color || paper,
      align: item.typography?.align || 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.name = item.role || 'headline';
    textGroup.add(textObject);
  }

  const foregroundRuleMaterial = new MeshBasicNodeMaterial({ color: paper });
  foregroundRuleMaterial.toneMapped = false;
  foregroundRuleMaterial.transparent = true;
  foregroundRuleMaterial.opacity = 0.28;

  const foregroundRuleGeometry = new PlaneGeometry(4.2, 0.012);
  const foregroundRule = new Mesh(foregroundRuleGeometry, foregroundRuleMaterial);
  foregroundRule.name = 'foreground-machined-rule';
  foregroundRule.position.set(0, -1.72, 0.25);
  foregroundRule.userData.__owned = true;
  root.add(foregroundRule);

  ownedGeometries.push(foregroundRuleGeometry);
  ownedMaterials.push(foregroundRuleMaterial);

  const entranceTimeline = gsap.timeline();
  entranceTimeline.fromTo(
    imageLayer.scale,
    { x: 0.985, y: 0.985, z: 1 },
    { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power3.out' }
  );
  timelines.push(entranceTimeline);

  const primitives = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];

  for (const primitive of primitives) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') continue;
    const result = ctx.primitives[primitive.name](root, primitive.params || {});
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    if (result?.timeline) timelines.push(result.timeline);
  }

  root.userData.cleanup = () => {
    if (root.userData.__cleaned) return;
    root.userData.__cleaned = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const cleanup of primitiveCleanups) {
      try {
        cleanup();
      } catch (_) {}
    }

    for (const geometry of ownedGeometries) geometry.dispose();
    for (const material of ownedMaterials) material.dispose();
  };

  return root;
}

export default createNode;
